import assert from "node:assert/strict";
import { test } from "node:test";

const receivedAtMs = 1_000_000;
const thirtyMinutes = 30 * 60_000;
const cases = [
  ["high", " high ", 0, "urgent"],
  ["normal before cutoff", "normal", thirtyMinutes - 1, "standard"],
  ["normal at cutoff", "normal", thirtyMinutes, "urgent"],
  ["future receipt", "normal", -1, "standard"],
  ["unknown before age", "unknown", thirtyMinutes, "triage"],
];

test("uses only the supplied clock at import and for routing", async (context) => {
  const clock = context.mock.method(Date, "now", () => {
    throw new Error("The domain must use the supplied nowMs");
  });
  const { selectQueue } = await import("./select-queue.mjs");
  for (const [name, priority, ageMs, queue] of cases) {
    await context.test(name, () => {
      assert.deepEqual(
        selectQueue({ priority, receivedAtMs, nowMs: receivedAtMs + ageMs }),
        { queue, rawPriority: priority },
      );
    });
  }
  assert.equal(clock.mock.callCount(), 0, "The domain read the ambient clock");
});

